//! `jira` noun-verb library logic: real SPARQL queries
//! (`crates/cng/src/queries/jira-*.rq`, generated by `jira-tracking-pack`
//! via `ggen sync`) executed against the ticket-tracking data compiled
//! into this binary (`crates/cng/src/jira-data.ttl`, generated by
//! `packs/jira-tracking-pack/make-ontology.py` from the real
//! `docs/jira/v26.7.11/tickets/index.md` markdown table — never
//! hand-typed).
//!
//! `crates/cng/src/jira_routes.rs` (also `ggen sync`-generated) is the
//! only caller of this module's [`handlers`] functions; see that file's
//! own header for why it lives in the binary crate while this module
//! lives in the library.
//!
//! No inline SPARQL: every query is `include_str!`-compiled from a `.rq`
//! file (`crates/cng/tests/no_inline_ttl_guard.rs` enforces this
//! crate-wide by grepping every `.rs` file for a literal SPARQL SELECT or
//! CONSTRUCT clause opener — deliberately not spelled out verbatim in this
//! sentence, for the same self-matching reason that guard test's own
//! needles are assembled from string parts rather than written literally).

use std::collections::BTreeMap;
use std::fmt;

use oxigraph::io::{RdfFormat, RdfParser};
use oxigraph::model::Term;
use oxigraph::sparql::{QueryResults, SparqlEvaluator};
use oxigraph::store::Store;
use serde::Serialize;

/// Compiled-in ticket-tracking ontology (schema + real parsed ticket
/// instances). GENERATED — see the file's own header for regeneration.
const JIRA_DATA_TTL: &str = include_str!("jira-data.ttl");

const Q_LIST: &str = include_str!("queries/jira-list.rq");
const Q_EVIDENCE: &str = include_str!("queries/jira-evidence.rq");
const Q_DEPS: &str = include_str!("queries/jira-deps.rq");
const Q_REPORT: &str = include_str!("queries/jira-report.rq");

/// Typed refusal taxonomy for the `jira` noun-verb commands (repo
/// invariant #1: no panics/silent defaults — every error here is one of
/// these variants; [`handlers`] converts to `clap_noun_verb::NounVerbError`
/// only at the CLI boundary).
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum JiraRefusal {
    /// `jira-data.ttl` failed to parse as Turtle. Should be unreachable
    /// outside development: the file is `ggen`-generated and
    /// `rapper -i turtle -c`-validated by `make-ontology.py`'s own
    /// generation step, never hand-edited.
    DataUnparseable(String),
    /// A compiled-in `.rq` query failed to parse.
    QueryParseFailed { query: &'static str, reason: String },
    /// A compiled-in `.rq` query executed but oxigraph reported a runtime
    /// error.
    QueryExecutionFailed { query: &'static str, reason: String },
    /// A query yielded a solution row missing an expected `?var` binding —
    /// would indicate the compiled-in `.rq` and `jira-data.ttl` have
    /// drifted out of sync with `schema.ttl`'s vocabulary.
    RowMissingBinding {
        query: &'static str,
        var: &'static str,
    },
    /// `jira show`/`status`/`deps` given an id with zero matching ticket.
    TicketNotFound(String),
}

impl fmt::Display for JiraRefusal {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::DataUnparseable(reason) => write!(f, "jira-data.ttl failed to parse: {reason}"),
            Self::QueryParseFailed { query, reason } => {
                write!(f, "query {query:?} failed to parse: {reason}")
            }
            Self::QueryExecutionFailed { query, reason } => {
                write!(f, "query {query:?} failed to execute: {reason}")
            }
            Self::RowMissingBinding { query, var } => {
                write!(f, "query {query:?} row missing ?{var} binding")
            }
            Self::TicketNotFound(id) => write!(f, "no ticket with id {id:?}"),
        }
    }
}

/// Builds a fresh in-memory store from the compiled-in ticket data.
///
/// # Complexity
/// O(n) in the byte length of `jira-data.ttl` — a single parse-and-insert
/// pass, oxigraph's own cost, not looped over here.
fn open_store() -> Result<Store, JiraRefusal> {
    let store = Store::new().map_err(|e| JiraRefusal::DataUnparseable(e.to_string()))?;
    store
        .load_from_slice(
            RdfParser::from_format(RdfFormat::Turtle),
            JIRA_DATA_TTL.as_bytes(),
        )
        .map_err(|e| JiraRefusal::DataUnparseable(e.to_string()))?;
    Ok(store)
}

fn term_value(term: &Term) -> String {
    match term {
        Term::Literal(l) => l.value().to_string(),
        Term::NamedNode(n) => n.as_str().to_string(),
        other => other.to_string(),
    }
}

/// Runs one compiled-in `.rq` SELECT query and returns its solutions as
/// `(var -> value-string)` rows, in the query's own `ORDER BY` order, for
/// exactly the caller-declared `vars` (matching `measurement.rs`'s proven
/// `solution.get("varname")` idiom, generalized to a caller-supplied var
/// list instead of two hardcoded names).
///
/// # Complexity
/// O(r * v) where r is the row count oxigraph's query execution returns
/// and v = `vars.len()` (no additional sorting/filtering here).
fn run_select(
    store: &Store,
    query: &'static str,
    vars: &[&'static str],
) -> Result<Vec<BTreeMap<String, String>>, JiraRefusal> {
    let prepared =
        SparqlEvaluator::new()
            .parse_query(query)
            .map_err(|e| JiraRefusal::QueryParseFailed {
                query,
                reason: e.to_string(),
            })?;
    let results =
        prepared
            .on_store(store)
            .execute()
            .map_err(|e| JiraRefusal::QueryExecutionFailed {
                query,
                reason: e.to_string(),
            })?;
    let mut rows = Vec::new();
    match results {
        QueryResults::Solutions(solutions) => {
            for solution in solutions {
                let solution = solution.map_err(|e| JiraRefusal::QueryExecutionFailed {
                    query,
                    reason: e.to_string(),
                })?;
                let mut row = BTreeMap::new();
                for var in vars {
                    let value = solution
                        .get(*var)
                        .map(term_value)
                        .ok_or(JiraRefusal::RowMissingBinding { query, var })?;
                    row.insert((*var).to_string(), value);
                }
                rows.push(row);
            }
        }
        _ => {
            return Err(JiraRefusal::QueryExecutionFailed {
                query,
                reason: "query did not yield SELECT solutions".to_string(),
            })
        }
    }
    Ok(rows)
}

/// Confirms `id` names a real ticket (runs [`Q_LIST`] filtered client-side
/// to `id`) so `jira show`/`status`/`deps` refuse [`JiraRefusal::TicketNotFound`]
/// instead of silently returning an empty result for a typo'd id — deps
/// in particular would otherwise be indistinguishable from "0
/// dependencies" (zero property-path hops and zero non-existence both
/// yield zero rows from `Q_DEPS` alone).
fn find_ticket_row(store: &Store, id: &str) -> Result<BTreeMap<String, String>, JiraRefusal> {
    let rows = run_select(store, Q_LIST, &["id", "title", "section", "statusLabel"])?;
    rows.into_iter()
        .find(|r| r.get("id").map(String::as_str) == Some(id))
        .ok_or_else(|| JiraRefusal::TicketNotFound(id.to_string()))
}

/// Reads a required field from a row [`run_select`] produced. Returns
/// [`JiraRefusal::RowMissingBinding`] instead of panicking/indexing if the
/// field is somehow absent — defensive even though `run_select`'s own
/// construction already guarantees every requested `var` is present in
/// every row it returns (invariant #1: no panics on data-derived paths,
/// even ones a nearby function already proves safe).
///
/// # Complexity
/// O(1) — a single `BTreeMap` lookup.
fn must<'a>(
    row: &'a BTreeMap<String, String>,
    query: &'static str,
    key: &'static str,
) -> Result<&'a String, JiraRefusal> {
    row.get(key)
        .ok_or(JiraRefusal::RowMissingBinding { query, var: key })
}

#[derive(Debug, Clone, Serialize)]
pub struct TicketSummary {
    pub id: String,
    pub title: String,
    pub section: String,
    pub status: String,
}

#[derive(Debug, Clone, Serialize)]
pub struct TicketListReport {
    pub count: usize,
    pub tickets: Vec<TicketSummary>,
}

#[derive(Debug, Clone, Serialize)]
pub struct TicketDetail {
    pub id: String,
    pub title: String,
    pub section: String,
    pub status: String,
    pub evidence: String,
    pub depends_on: Vec<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct TicketStatus {
    pub id: String,
    pub status: String,
}

#[derive(Debug, Clone, Serialize)]
pub struct TicketDeps {
    pub id: String,
    pub depends_on: Vec<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct StatusCount {
    pub status: String,
    pub count: u64,
}

#[derive(Debug, Clone, Serialize)]
pub struct TicketReport {
    pub total: u64,
    pub by_status: Vec<StatusCount>,
}

/// Real, non-generated command handlers — `jira_routes.rs` (`ggen`
/// generated) is this module's only caller. Each handler builds a fresh
/// [`Store`] from the compiled-in ticket data, runs one or more real
/// compiled-in `.rq` queries, and maps the solutions into a typed report.
pub mod handlers {
    use super::{
        find_ticket_row, must, open_store, run_select, JiraRefusal, StatusCount, TicketDeps,
        TicketDetail, TicketListReport, TicketReport, TicketStatus, TicketSummary, Q_DEPS,
        Q_EVIDENCE, Q_LIST, Q_REPORT,
    };

    fn to_cli_error(e: JiraRefusal) -> clap_noun_verb::NounVerbError {
        clap_noun_verb::NounVerbError::execution_error(format!("CNG_JIRA: {e}"))
    }

    /// Lists all tickets, optionally filtered by `--status`/`--section`
    /// (exact string match against the SPARQL-projected `statusLabel`/
    /// `section` values; filtering happens in Rust over an already-fetched
    /// real result set, not by hand-typing a second SPARQL query per
    /// filter combination).
    pub fn jira_list_handler(
        status: Option<String>,
        section: Option<String>,
    ) -> clap_noun_verb::Result<TicketListReport> {
        let store = open_store().map_err(to_cli_error)?;
        let rows = run_select(&store, Q_LIST, &["id", "title", "section", "statusLabel"])
            .map_err(to_cli_error)?;
        let mut tickets = Vec::new();
        for row in &rows {
            let st = must(row, Q_LIST, "statusLabel").map_err(to_cli_error)?;
            let sect = must(row, Q_LIST, "section").map_err(to_cli_error)?;
            if status.as_deref().is_some_and(|want| want != st) {
                continue;
            }
            if section.as_deref().is_some_and(|want| want != sect) {
                continue;
            }
            tickets.push(TicketSummary {
                id: must(row, Q_LIST, "id").map_err(to_cli_error)?.clone(),
                title: must(row, Q_LIST, "title").map_err(to_cli_error)?.clone(),
                section: sect.clone(),
                status: st.clone(),
            });
        }
        Ok(TicketListReport {
            count: tickets.len(),
            tickets,
        })
    }

    /// Full detail for one ticket id: title/section/status, the complete
    /// evidence text, and its full transitive dependency chain.
    pub fn jira_show_handler(id: String) -> clap_noun_verb::Result<TicketDetail> {
        let store = open_store().map_err(to_cli_error)?;
        let row = find_ticket_row(&store, &id).map_err(to_cli_error)?;

        let ev_rows = run_select(&store, Q_EVIDENCE, &["id", "evidence"]).map_err(to_cli_error)?;
        let evidence = match ev_rows
            .iter()
            .find(|r| r.get("id").map(String::as_str) == Some(id.as_str()))
        {
            Some(r) => must(r, Q_EVIDENCE, "evidence")
                .map_err(to_cli_error)?
                .clone(),
            // A ticket with zero evidence text is not expected in real data
            // (every parsed row has a non-empty Scope cell) but is not an
            // error either — an empty string is the honest representation.
            None => String::new(),
        };

        let dep_rows = run_select(&store, Q_DEPS, &["id", "dep"]).map_err(to_cli_error)?;
        let mut depends_on = Vec::new();
        for r in dep_rows
            .iter()
            .filter(|r| r.get("id").map(String::as_str) == Some(id.as_str()))
        {
            depends_on.push(must(r, Q_DEPS, "dep").map_err(to_cli_error)?.clone());
        }

        Ok(TicketDetail {
            id: must(&row, Q_LIST, "id").map_err(to_cli_error)?.clone(),
            title: must(&row, Q_LIST, "title").map_err(to_cli_error)?.clone(),
            section: must(&row, Q_LIST, "section").map_err(to_cli_error)?.clone(),
            status: must(&row, Q_LIST, "statusLabel")
                .map_err(to_cli_error)?
                .clone(),
            evidence,
            depends_on,
        })
    }

    /// Just the status line for one ticket id.
    pub fn jira_status_handler(id: String) -> clap_noun_verb::Result<TicketStatus> {
        let store = open_store().map_err(to_cli_error)?;
        let row = find_ticket_row(&store, &id).map_err(to_cli_error)?;
        Ok(TicketStatus {
            id: must(&row, Q_LIST, "id").map_err(to_cli_error)?.clone(),
            status: must(&row, Q_LIST, "statusLabel")
                .map_err(to_cli_error)?
                .clone(),
        })
    }

    /// The full transitive dependency chain for one ticket id (real
    /// SPARQL 1.1 `jira:dependsOn+` property path, not a Rust-side
    /// graph walk).
    pub fn jira_deps_handler(id: String) -> clap_noun_verb::Result<TicketDeps> {
        let store = open_store().map_err(to_cli_error)?;
        // Confirms the id itself is real before reporting an (otherwise
        // ambiguous) empty dependency list.
        find_ticket_row(&store, &id).map_err(to_cli_error)?;
        let rows = run_select(&store, Q_DEPS, &["id", "dep"]).map_err(to_cli_error)?;
        let mut depends_on = Vec::new();
        for r in rows
            .iter()
            .filter(|r| r.get("id").map(String::as_str) == Some(id.as_str()))
        {
            depends_on.push(must(r, Q_DEPS, "dep").map_err(to_cli_error)?.clone());
        }
        Ok(TicketDeps { id, depends_on })
    }

    /// Summary counts of tickets per status (real SPARQL `GROUP BY`/
    /// `COUNT`, not a Rust-side tally).
    pub fn jira_report_handler() -> clap_noun_verb::Result<TicketReport> {
        let store = open_store().map_err(to_cli_error)?;
        let rows = run_select(&store, Q_REPORT, &["statusLabel", "count"]).map_err(to_cli_error)?;
        let mut by_status = Vec::new();
        let mut total: u64 = 0;
        for row in &rows {
            let count_text = must(row, Q_REPORT, "count").map_err(to_cli_error)?;
            let count: u64 = count_text.parse().map_err(|e| {
                to_cli_error(JiraRefusal::QueryExecutionFailed {
                    query: Q_REPORT,
                    reason: format!("count {count_text:?} did not parse as u64: {e}"),
                })
            })?;
            total += count;
            by_status.push(StatusCount {
                status: must(row, Q_REPORT, "statusLabel")
                    .map_err(to_cli_error)?
                    .clone(),
                count,
            });
        }
        Ok(TicketReport { total, by_status })
    }
}

#[cfg(test)]
mod tests {
    use super::handlers::*;

    #[test]
    fn list_returns_all_49_real_tickets() {
        let report = jira_list_handler(None, None).expect("real compiled-in data must query");
        assert_eq!(report.count, 49);
        assert_eq!(report.tickets.len(), 49);
    }

    #[test]
    fn list_filters_by_status() {
        let report = jira_list_handler(Some("ALIVE".to_string()), None).expect("query");
        assert_eq!(report.count, 33);
        assert!(report.tickets.iter().all(|t| t.status == "ALIVE"));
    }

    #[test]
    fn list_filters_by_section() {
        let report = jira_list_handler(None, Some("A".to_string())).expect("query");
        assert!(report.tickets.iter().all(|t| t.section == "A"));
        assert!(!report.tickets.is_empty());
    }

    #[test]
    fn show_returns_full_detail_for_a_real_ticket() {
        let detail = jira_show_handler("750".to_string()).expect("750 is real");
        assert_eq!(detail.id, "750");
        assert!(detail.title.contains("POWL v2"));
        assert_eq!(detail.status, "ALIVE");
        assert!(!detail.evidence.is_empty());
        assert!(
            detail.depends_on.is_empty(),
            "750 has no declared dependencies"
        );
    }

    #[test]
    fn show_refuses_unknown_id() {
        let err = jira_show_handler("999999".to_string()).unwrap_err();
        assert!(format!("{err}").contains("CNG_JIRA"));
    }

    #[test]
    fn status_returns_just_the_status_line() {
        let status = jira_status_handler("777".to_string()).expect("777 is real");
        assert_eq!(status.id, "777");
        assert_eq!(status.status, "ALIVE");
    }

    #[test]
    fn deps_returns_the_real_transitive_chain() {
        // 753 -> 752 -> 751 -> 750 (direct chain per the real table).
        let deps = jira_deps_handler("753".to_string()).expect("753 is real");
        assert!(deps.depends_on.contains(&"752".to_string()));
        assert!(deps.depends_on.contains(&"751".to_string()));
        assert!(deps.depends_on.contains(&"750".to_string()));
    }

    #[test]
    fn deps_on_dependency_free_ticket_is_empty_not_refused() {
        let deps = jira_deps_handler("750".to_string()).expect("750 is real, zero deps");
        assert!(deps.depends_on.is_empty());
    }

    #[test]
    fn deps_refuses_unknown_id() {
        assert!(jira_deps_handler("999999".to_string()).is_err());
    }

    #[test]
    fn report_totals_match_the_real_49_tickets() {
        let report = jira_report_handler().expect("query");
        assert_eq!(report.total, 49);
        let alive = report
            .by_status
            .iter()
            .find(|s| s.status == "ALIVE")
            .expect("ALIVE present");
        assert_eq!(alive.count, 33);
    }

    #[test]
    fn list_is_deterministic_across_two_calls() {
        let a = jira_list_handler(None, None).expect("query");
        let b = jira_list_handler(None, None).expect("query");
        assert_eq!(
            a.tickets.iter().map(|t| t.id.clone()).collect::<Vec<_>>(),
            b.tickets.iter().map(|t| t.id.clone()).collect::<Vec<_>>(),
        );
    }
}
